#!/bin/sh
# Goal: Reset git repository while preserving prompt.yaml
# Plan:
# 1. Create a new directory named 'scripts' to hold utility scripts like the one being created.
# 2. In 'scripts', create a new JavaScript file named 'resetGit.js' that will implement the required function. 
#    This function will make use of child_process package's execSync method to execute git commands.
# 3. The function will perform the following steps:
#    a. Stash the changes of prompt.yaml file to keep them safe.
#    b. Execute git clean command to remove all untracked and ignored files.
#    c. Reset the git repository to the latest commit.
#    d. Pop the stashed changes to restore the changes made to the prompt.yaml file.
# 4. In 'scripts', create a new JavaScript file named 'index.js' that will import and run the resetGit function from resetGit.js file.

mkdir -p scripts

cat << EOF > scripts/resetGit.js
import { execSync } from 'child_process';

export default function resetGit() {
  // Stash changes in prompt.yaml
  execSync('git add ./prompt.yaml && git stash');

  // Clean the repository and reset to the latest commit
  execSync('git clean -fd && git reset --hard HEAD');

  // Apply stashed changes to prompt.yaml
  execSync('git stash pop');
}
EOF

cat << EOF > scripts/index.js
import resetGit from './resetGit.js';

resetGit();
EOF

